package com.dongqh.luckyhub.coupon;
import com.dongqh.luckyhub.coupon.dto.*; import com.dongqh.luckyhub.coupon.enums.CouponType; import com.dongqh.luckyhub.coupon.service.CouponService; import com.dongqh.luckyhub.rbac.entity.SysUser; import com.dongqh.luckyhub.rbac.mapper.SysUserMapper; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.jdbc.core.JdbcTemplate; import java.time.LocalDateTime; import java.util.*; import java.util.concurrent.*; import static org.assertj.core.api.Assertions.assertThat;
@SpringBootTest class CouponConcurrencyTests {
 @Autowired CouponService service;@Autowired JdbcTemplate jdbc;@Autowired SysUserMapper users;Long userId;Long couponId;
 @BeforeEach void setup(){jdbc.update("DELETE FROM coupon_issue_record");jdbc.update("DELETE FROM user_coupon");jdbc.update("DELETE FROM coupon_template");SysUser u=new SysUser();u.setUsername("cc-"+UUID.randomUUID());u.setPassword("x");u.setNickname("并发券用户");u.setStatus(1);users.insert(u);userId=u.getId();var t=service.createTemplate(new CreateCouponTemplateCommand("CC","并发券",CouponType.NO_THRESHOLD,0L,100L,null,LocalDateTime.now().minusDays(1),LocalDateTime.now().plusDays(2),1,true));couponId=service.issue(new IssueCouponCommand("CCI","CCU",t.id(),userId)).id();}
 @AfterEach void clean(){jdbc.update("DELETE FROM coupon_issue_record");jdbc.update("DELETE FROM user_coupon");jdbc.update("DELETE FROM coupon_template");users.deleteById(userId);}
 @Test void onlyOneOfTwoOrdersLocksOneCoupon() throws Exception {var pool=Executors.newFixedThreadPool(2);var gate=new CountDownLatch(1);List<Future<Boolean>> fs=new ArrayList<>();for(int i=0;i<2;i++){String o="RACE-"+i;fs.add(pool.submit(()->{gate.await();try{service.lockForOrder(userId,couponId,o,null,1000L,false);return true;}catch(Exception e){return false;}}));}gate.countDown();int success=0;for(var f:fs)if(f.get())success++;pool.shutdown();assertThat(success).isOne();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM user_coupon WHERE id=? AND status='LOCKED'",Integer.class,couponId)).isOne();}
}
